class Solution:
    def longestCommonSubpath(self, n: int, paths: List[List[int]]) -> int:
        import random
        MOD = (1 << 61) - 1
        BASE = random.randint(10**5, 10**6)
        def get_hashes(path, length):
            if length == 0: return set()
            h, pw = 0, 1
            for i in range(length):
                h = (h * BASE + path[i]) % MOD
                if i < length - 1: pw = pw * BASE % MOD
            res = {h}
            for i in range(length, len(path)):
                h = (h - path[i - length] * pw) % MOD
                h = (h * BASE + path[i]) % MOD
                res.add(h)
            return res
        lo, hi = 0, min(len(p) for p in paths)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            common = get_hashes(paths[0], mid)
            for p in paths[1:]:
                common &= get_hashes(p, mid)
                if not common: break
            if common: lo = mid
            else: hi = mid - 1
        return lo

class Solution:
    def outerTrees(self, trees: List[List[int]]) -> List[float]:
        import random, math
        def dist(a, b): return math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2)
        def circle_from_2(a, b): return [(a[0]+b[0])/2, (a[1]+b[1])/2, dist(a,b)/2]
        def circle_from_3(a, b, c):
            ax,ay,bx,by,cx,cy = a[0],a[1],b[0],b[1],c[0],c[1]
            D = 2*(ax*(by-cy)+bx*(cy-ay)+cx*(ay-by))
            if D == 0: return None
            ux = ((ax*ax+ay*ay)*(by-cy)+(bx*bx+by*by)*(cy-ay)+(cx*cx+cy*cy)*(ay-by))/D
            uy = ((ax*ax+ay*ay)*(cx-bx)+(bx*bx+by*by)*(ax-cx)+(cx*cx+cy*cy)*(bx-ax))/D
            return [ux, uy, dist([ux,uy], a)]
        def in_circle(c, p): return dist(c, p) <= c[2] + 1e-7
        random.shuffle(trees)
        c = [trees[0][0], trees[0][1], 0.0]
        for i in range(1, len(trees)):
            if not in_circle(c, trees[i]):
                c = [trees[i][0], trees[i][1], 0.0]
                for j in range(i):
                    if not in_circle(c, trees[j]):
                        c = circle_from_2(trees[i], trees[j])
                        for k in range(j):
                            if not in_circle(c, trees[k]):
                                c = circle_from_3(trees[i], trees[j], trees[k])
        return c

class Solution:
    def countTriples(self, n: int) -> int:
        import math
        count = 0
        for a in range(1, n + 1):
            for b in range(a, n + 1):
                c_sq = a * a + b * b
                c = int(math.isqrt(c_sq))
                if c * c == c_sq and c <= n:
                    count += 2 if a != b else 1
        return count

class Solution:
    def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:
        from collections import deque
        m, n = len(maze), len(maze[0])
        q = deque([(entrance[0], entrance[1], 0)])
        maze[entrance[0]][entrance[1]] = '+'
        for r, c, d in q:
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < m and 0 <= nc < n and maze[nr][nc] == '.':
                    if nr == 0 or nr == m-1 or nc == 0 or nc == n-1:
                        return d + 1
                    maze[nr][nc] = '+'
                    q.append((nr, nc, d+1))
        return -1

class Solution:
    def sumGame(self, num: str) -> bool:
        n = len(num)
        half = n // 2
        s1, q1, s2, q2 = 0, 0, 0, 0
        for i in range(half):
            if num[i] == '?': q1 += 1
            else: s1 += int(num[i])
        for i in range(half, n):
            if num[i] == '?': q2 += 1
            else: s2 += int(num[i])
        if (q1 + q2) % 2 == 1:
            return True
        return s1 - s2 != 9 * (q2 - q1) // 2

class Solution:
    def minCost(self, maxTime: int, edges: List[List[int]], passingFees: List[int]) -> int:
        n = len(passingFees)
        dp = [[float('inf')] * n for _ in range(maxTime + 1)]
        dp[0][0] = passingFees[0]
        for t in range(1, maxTime + 1):
            for u, v, w in edges:
                if t >= w:
                    if dp[t-w][u] < float('inf'):
                        dp[t][v] = min(dp[t][v], dp[t-w][u] + passingFees[v])
                    if dp[t-w][v] < float('inf'):
                        dp[t][u] = min(dp[t][u], dp[t-w][v] + passingFees[u])
        ans = min(dp[t][n-1] for t in range(maxTime+1))
        return ans if ans < float('inf') else -1

