class Solution:
    def colorTheGrid(self, m: int, n: int) -> int:
        MOD = 10**9 + 7
        from itertools import product
        # Generate valid columns (no adjacent same color)
        valid = []
        for col in product(range(3), repeat=m):
            if all(col[i] != col[i+1] for i in range(m-1)):
                valid.append(col)
        # Check compatibility between two columns
        def compatible(c1, c2):
            return all(a != b for a, b in zip(c1, c2))
        # Build transition
        trans = {v: [u for u in valid if compatible(v, u)] for v in valid}
        dp = {v: 1 for v in valid}
        for _ in range(n - 1):
            ndp = {}
            for v in valid:
                ndp[v] = sum(dp.get(u, 0) for u in trans[v]) % MOD
            dp = ndp
        return sum(dp.values()) % MOD

class Solution:
    def canMerge(self, trees: List[TreeNode]) -> Optional[TreeNode]:
        from collections import Counter
        root_map = {t.val: t for t in trees}
        leaf_count = Counter()
        for t in trees:
            if t.left: leaf_count[t.left.val] += 1
            if t.right: leaf_count[t.right.val] += 1
        roots = [t for t in trees if t.val not in leaf_count]
        if len(roots) != 1: return None
        def merge(node, lo, hi):
            if not node: return True
            if node.val <= lo or node.val >= hi: return False
            if node.val in root_map and node != root_map[node.val]:
                target = root_map[node.val]
                node.left, node.right = target.left, target.right
            return merge(node.left, lo, node.val) and merge(node.right, node.val, hi)
        return roots[0] if merge(roots[0], float('-inf'), float('inf')) else None

