class Solution:
    def maxPoints(self, points: List[List[int]]) -> int:
        m, n = len(points), len(points[0])
        dp = points[0][:]
        for i in range(1, m):
            left = [0] * n
            left[0] = dp[0]
            for j in range(1, n):
                left[j] = max(left[j-1], dp[j] + j)
            right = [0] * n
            right[-1] = dp[-1] - (n-1)
            for j in range(n-2, -1, -1):
                right[j] = max(right[j+1], dp[j] - j)
            for j in range(n):
                dp[j] = points[i][j] + max(left[j] - j, right[j] + j)
        return max(dp)

class Solution:
    def maxGeneticDifference(self, parents: List[int], queries: List[List[int]]) -> List[int]:
        from collections import defaultdict
        n = len(parents)
        children = defaultdict(list)
        root = -1
        for i, p in enumerate(parents):
            if p == -1: root = i
            else: children[p].append(i)
        qmap = defaultdict(list)
        for idx, (node, val) in enumerate(queries):
            qmap[node].append((val, idx))
        trie = [[None, None]]
        cnt = [0]
        def add(num):
            cur = 0
            for i in range(17, -1, -1):
                bit = (num >> i) & 1
                if trie[cur][bit] is None:
                    trie.append([None, None])
                    cnt.append(0)
                    trie[cur][bit] = len(trie) - 1
                cur = trie[cur][bit]
                cnt[cur] += 1
        def remove(num):
            cur = 0
            for i in range(17, -1, -1):
                bit = (num >> i) & 1
                cur = trie[cur][bit]
                cnt[cur] -= 1
        def query(num):
            cur, res = 0, 0
            for i in range(17, -1, -1):
                bit = (num >> i) & 1
                want = 1 - bit
                if trie[cur][want] is not None and cnt[trie[cur][want]] > 0:
                    res |= (1 << i)
                    cur = trie[cur][want]
                else:
                    cur = trie[cur][bit]
            return res
        ans = [0] * len(queries)
        stack = [(root, False)]
        while stack:
            node, leaving = stack.pop()
            if leaving:
                remove(node)
                continue
            add(node)
            stack.append((node, True))
            for val, idx in qmap[node]:
                ans[idx] = query(val)
            for ch in children[node]:
                stack.append((ch, False))
        return ans

