class Solution:
    def maxCompatibilitySum(self, students: List[List[int]], mentors: List[List[int]]) -> int:
        m = len(students)
        n = len(students[0])
        score = [[sum(s[k] == t[k] for k in range(n)) for t in mentors] for s in students]
        dp = [0] * (1 << m)
        for mask in range(1, 1 << m):
            i = bin(mask).count('1') - 1
            for j in range(m):
                if mask & (1 << j):
                    dp[mask] = max(dp[mask], dp[mask ^ (1 << j)] + score[i][j])
        return dp[(1 << m) - 1]

class Solution:
    def deleteDuplicateFolder(self, paths: List[List[str]]) -> List[List[str]]:
        from collections import defaultdict
        root = {}
        for path in paths:
            node = root
            for p in path:
                node = node.setdefault(p, {})
        serial_count = defaultdict(int)
        serial_map = {}
        def serialize(node):
            if not node: return ""
            parts = []
            for k in sorted(node):
                parts.append(f"({k}{serialize(node[k])})")
            s = ''.join(parts)
            if s:
                serial_count[s] += 1
                serial_map[id(node)] = s
            return s
        serialize(root)
        res = []
        def collect(node, path):
            for k in sorted(node):
                child = node[k]
                s = serial_map.get(id(child), "")
                if s and serial_count[s] > 1:
                    continue
                path.append(k)
                res.append(path[:])
                collect(child, path)
                path.pop()
        collect(root, [])
        return res

class Solution:
    def findMaximums(self, nums: List[int]) -> List[int]:
        n = len(nums)
        left = [-1] * n
        right = [n] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            left[i] = stack[-1] if stack else -1
            stack.append(i)
        stack = []
        for i in range(n-1, -1, -1):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            right[i] = stack[-1] if stack else n
            stack.append(i)
        res = [0] * n
        for i in range(n):
            length = right[i] - left[i] - 2
            res[length] = max(res[length], nums[i])
        for i in range(n-2, -1, -1):
            res[i] = max(res[i], res[i+1])
        return res

class Solution:
    def isThree(self, n: int) -> bool:
        import math
        sr = int(math.isqrt(n))
        if sr * sr != n:
            return False
        if sr < 2:
            return False
        for i in range(2, int(math.isqrt(sr)) + 1):
            if sr % i == 0:
                return False
        return True

