class Solution:
    def countSpecialSubsequences(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp0 = dp1 = dp2 = 0
        for x in nums:
            if x == 0:
                dp0 = (dp0 * 2 + 1) % MOD
