class Solution:
    def minSpaceWastedKResizing(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [[float('inf')] * (k + 2) for _ in range(n + 1)]
        dp[0][0] = 0
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + nums[i]
        for i in range(1, n + 1):
            for j in range(min(i, k + 1) + 1):
                mx = 0
                for l in range(i, 0, -1):
                    mx = max(mx, nums[l-1])
                    waste = mx * (i - l + 1) - (prefix[i] - prefix[l-1])
                    if j > 0:
                        dp[i][j] = min(dp[i][j], dp[l-1][j-1] + waste)
                    elif l == 1:
                        dp[i][0] = min(dp[i][0], waste)
        return min(dp[n])

class Solution:
    def maxProduct(self, s: str) -> int:
        n = len(s)
        # Manacher for odd palindromes
        p = [0] * n
        c = r = 0
        for i in range(n):
            mirror = 2 * c - i
            if i < r:
                p[i] = min(r - i, p[mirror])
            while i - p[i] - 1 >= 0 and i + p[i] + 1 < n and s[i - p[i] - 1] == s[i + p[i] + 1]:
                p[i] += 1
            if i + p[i] > r:
                c, r = i, i + p[i]
        # maxL[i] = longest odd palindrome ending at or before i
        maxL = [0] * n
        # maxR[i] = longest odd palindrome starting at or after i
        maxR = [0] * n
        # Use p to fill maxL: palindrome centered at i has length 2*p[i]+1, ends at i+p[i]
        for i in range(n):
            maxL[i + p[i]] = max(maxL[i + p[i]] if i + p[i] < n else 0, 2 * p[i] + 1)
        # Propagate: if maxL[i] = L, then maxL[i-1] >= L-2
        for i in range(n - 1, 0, -1):
            maxL[i-1] = max(maxL[i-1], maxL[i] - 2)
        # Forward pass to get prefix max
        for i in range(1, n):
            maxL[i] = max(maxL[i], maxL[i-1])
        for i in range(n):
            maxR[i - p[i]] = max(maxR[i - p[i]] if i - p[i] >= 0 else 0, 2 * p[i] + 1)
        for i in range(0, n - 1):
            maxR[i+1] = max(maxR[i+1], maxR[i] - 2)
        for i in range(n - 2, -1, -1):
            maxR[i] = max(maxR[i], maxR[i+1])
        ans = 0
        for i in range(n - 1):
            ans = max(ans, maxL[i] * maxR[i+1])
        return ans

