class Solution:
    def minStoneSum(self, piles: List[int], k: int) -> int:
        import heapq
        heap = [-p for p in piles]
        heapq.heapify(heap)
        for _ in range(k):
            mx = -heapq.heappop(heap)
            heapq.heappush(heap, -(mx - mx // 2))
        return -sum(heap)

class Solution:
    def minSwaps(self, s: str) -> int:
        unmatched = 0
        open_count = 0
        for c in s:
            if c == '[':
                open_count += 1
            else:
                if open_count > 0:
                    open_count -= 1
                else:
                    unmatched += 1
        return (unmatched + 1) // 2

class Solution:
    def longestObstacleCourseAtEachPosition(self, obstacles: List[int]) -> List[int]:
        import bisect
        tails = []
        res = []
        for x in obstacles:
            pos = bisect.bisect_right(tails, x)
            if pos == len(tails):
                tails.append(x)
            else:
                tails[pos] = x
            res.append(pos + 1)
        return res

class Solution:
    def binarySearchableNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        prefix_max = [float('-inf')] * n
        suffix_min = [float('inf')] * n
        for i in range(1, n):
            prefix_max[i] = max(prefix_max[i-1], nums[i-1])
        for i in range(n-2, -1, -1):
            suffix_min[i] = min(suffix_min[i+1], nums[i+1])
        return sum(1 for i in range(n) if prefix_max[i] < nums[i] < suffix_min[i])

