class Solution:
    def latestDayToCross(self, row: int, col: int, cells: List[List[int]]) -> int:
        from collections import deque
        def canCross(day):
            grid = [[0]*col for _ in range(row)]
            for i in range(day):
                r, c = cells[i]
                grid[r-1][c-1] = 1
            q = deque()
            for j in range(col):
                if grid[0][j] == 0:
                    q.append((0, j))
                    grid[0][j] = 1
            while q:
                r, c = q.popleft()
                if r == row - 1:
                    return True
                for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < row and 0 <= nc < col and grid[nr][nc] == 0:
                        grid[nr][nc] = 1
                        q.append((nr, nc))
            return False
        lo, hi = 1, len(cells)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if canCross(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def validPath(self, n: int, edges: List[List[int]], source: int, destination: int) -> bool:
        from collections import defaultdict, deque
        if source == destination: return True
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        visited = {source}
        q = deque([source])
        while q:
            node = q.popleft()
            for nei in graph[node]:
                if nei == destination:
                    return True
                if nei not in visited:
                    visited.add(nei)
                    q.append(nei)
        return False

class Solution:
    def equalToDescendants(self, root: Optional[TreeNode]) -> int:
        self.count = 0
        def dfs(node):
            if not node: return 0
            left = dfs(node.left)
            right = dfs(node.right)
            if node.val == left + right and (node.left or node.right):
                self.count += 1
            return node.val + left + right
        dfs(root)
        return self.count

class Solution:
    def minTimeToType(self, word: str) -> int:
        res = 0
        cur = 0  # 'a'
        for c in word:
            target = ord(c) - ord('a')
            diff = abs(target - cur)
            res += min(diff, 26 - diff) + 1
            cur = target
        return res

class Solution:
    def maxMatrixSum(self, matrix: List[List[int]]) -> int:
        total = 0
        min_abs = float('inf')
        neg_count = 0
        for row in matrix:
            for x in row:
                total += abs(x)
                min_abs = min(min_abs, abs(x))
                if x < 0:
                    neg_count += 1
        if neg_count % 2 == 0:
            return total
        return total - 2 * min_abs

class Solution:
    def numberOfCombinations(self, num: str) -> int:
        if num[0] == '0': return 0
        n = len(num)
        MOD = 10**9 + 7
        # LCP[i][j] = longest common prefix of num[i:] and num[j:]
        lcp = [[0]*(n+1) for _ in range(n+1)]
        for i in range(n-1, -1, -1):
            for j in range(n-1, -1, -1):
                if num[i] == num[j]:
                    lcp[i][j] = lcp[i+1][j+1] + 1
        def le(i, j, length):
            l = lcp[i][j]
            if l >= length: return True
            return num[i+l] <= num[j+l]
        # dp[i][j] = ways where last number starts at j and ends at i
        # prefix[i][j] = sum(dp[i][0..j])
        dp = [[0]*(n) for _ in range(n)]
        prefix = [[0]*(n+1) for _ in range(n)]
        for i in range(n):
            for j in range(i+1):
                if num[j] == '0':
                    dp[i][j] = 0
                elif j == 0:
                    dp[i][j] = 1
                else:
                    length = i - j + 1
                    prev_start = j - length
                    if prev_start >= 0:
                        if le(prev_start, j, length):
                            dp[i][j] = prefix[j-1][prev_start+1] % MOD
                        else:
                            dp[i][j] = prefix[j-1][prev_start] % MOD
                    else:
                        dp[i][j] = prefix[j-1][0] % MOD
            prefix[i][0] = dp[i][0]
            for j in range(1, n):
                prefix[i][j] = (prefix[i][j-1] + dp[i][j]) % MOD
        return sum(dp[n-1]) % MOD

class Solution:
    def findGCD(self, nums: List[int]) -> int:
        from math import gcd
        return gcd(min(nums), max(nums))

class Solution:
    def findDifferentBinaryString(self, nums: List[str]) -> str:
        return ''.join('1' if nums[i][i] == '0' else '0' for i in range(len(nums)))
